"""In-memory B-tree of order 4 (max 3 keys per node), stdlib only.

Semantics: set-like (duplicate inserts are ignored, deleting a missing key
is a no-op). Supports insert, search, delete, in-order iteration, plus a
public invariant checker useful for testing.

Implementation follows the classic CLRS algorithms:
  * insert uses proactive splitting (split-full-child on the way down),
  * delete uses borrowing from siblings and merging of children, with the
    root shrinking whenever it ends up with zero keys after a merge.
"""

from bisect import bisect_left

MAX_KEYS = 3                 # order 4 => at most 3 keys per node
MIN_KEYS = MAX_KEYS // 2     # => every non-root node holds at least 1 key


class _Node:
    """A single B-tree node. `children` is None for leaves."""

    __slots__ = ("keys", "children")

    def __init__(self, leaf=True):
        self.keys = []
        self.children = None if leaf else []

    @property
    def leaf(self):
        return self.children is None


class BTree:
    def __init__(self):
        self._root = _Node(leaf=True)
        # Counters so callers/tests can verify structural events occurred.
        self.stats = {"splits": 0, "merges": 0, "borrows": 0}

    # ------------------------------------------------------------------ #
    # Search                                                             #
    # ------------------------------------------------------------------ #

    def search(self, key):
        """Return True if `key` is present."""
        return self._search(self._root, key)

    def _search(self, node, key):
        i = bisect_left(node.keys, key)
        if i < len(node.keys) and node.keys[i] == key:
            return True
        if node.leaf:
            return False
        return self._search(node.children[i], key)

    # ------------------------------------------------------------------ #
    # Insert                                                             #
    # ------------------------------------------------------------------ #

    def insert(self, key):
        """Insert `key`; ignored if already present."""
        if self.search(key):
            return
        root = self._root
        if len(root.keys) == MAX_KEYS:
            new_root = _Node(leaf=False)
            new_root.children.append(root)
            self._split_child(new_root, 0)
            self._root = new_root
            self._insert_nonfull(new_root, key)
        else:
            self._insert_nonfull(root, key)

    def _split_child(self, parent, i):
        child = parent.children[i]
        mid = len(child.keys) // 2
        right = _Node(leaf=child.leaf)
        right.keys = child.keys[mid + 1:]
        promoted = child.keys[mid]
        if not child.leaf:
            right.children = child.children[mid + 1:]
            child.children = child.children[: mid + 1]
        child.keys = child.keys[:mid]
        parent.keys.insert(i, promoted)
        parent.children.insert(i + 1, right)
        self.stats["splits"] += 1

    def _insert_nonfull(self, node, key):
        if node.leaf:
            node.keys.insert(bisect_left(node.keys, key), key)
            return
        i = bisect_left(node.keys, key)
        if len(node.children[i].keys) == MAX_KEYS:
            self._split_child(node, i)
            if key > node.keys[i]:
                i += 1
        self._insert_nonfull(node.children[i], key)

    # ------------------------------------------------------------------ #
    # Delete                                                             #
    # ------------------------------------------------------------------ #

    def delete(self, key):
        """Delete `key`; no-op if absent."""
        self._delete(self._root, key)
        # Root shrink: drop the old root once it holds no keys after a merge.
        if not self._root.leaf and len(self._root.keys) == 0:
            self._root = self._root.children[0]

    def _delete(self, node, key):
        i = bisect_left(node.keys, key)
        found = i < len(node.keys) and node.keys[i] == key

        if node.leaf:
            if found:
                node.keys.pop(i)
            return

        if found:
            left, right = node.children[i], node.children[i + 1]
            if len(left.keys) > MIN_KEYS:
                # Replace with in-order predecessor, then delete it below.
                pred = self._max(left)
                node.keys[i] = pred
                self._delete(left, pred)
            elif len(right.keys) > MIN_KEYS:
                # Replace with in-order successor, then delete it below.
                succ = self._min(right)
                node.keys[i] = succ
                self._delete(right, succ)
            else:
                # Both children are minimal: fuse them together with `key`.
                self._merge_children(node, i)
                self._delete(node.children[i], key)
            return

        # Key not in this node: make sure the child we descend into has
        # more than the minimum number of keys.
        if len(node.children[i].keys) == MIN_KEYS:
            self._fill(node, i)
        # If children[i] was just fused with its left sibling, step back.
        if i > len(node.keys):
            i -= 1
        self._delete(node.children[i], key)

    def _fill(self, parent, i):
        """Ensure parent.children[i] has more than MIN_KEYS keys."""
        if i > 0 and len(parent.children[i - 1].keys) > MIN_KEYS:
            self._borrow_from_prev(parent, i)
        elif i < len(parent.keys) and len(parent.children[i + 1].keys) > MIN_KEYS:
            self._borrow_from_next(parent, i)
        else:
            if i < len(parent.keys):
                self._merge_children(parent, i)
            else:
                self._merge_children(parent, i - 1)

    def _merge_children(self, parent, i):
        """Fuse parent.children[i], parent.keys[i] and parent.children[i+1]."""
        left, right = parent.children[i], parent.children[i + 1]
        left.keys.append(parent.keys.pop(i))
        left.keys.extend(right.keys)
        if not left.leaf:
            left.children.extend(right.children)
        parent.children.pop(i + 1)
        self.stats["merges"] += 1

    def _borrow_from_prev(self, parent, i):
        """Rotate a key from the left sibling into children[i]."""
        child, sibling = parent.children[i], parent.children[i - 1]
        child.keys.insert(0, parent.keys[i - 1])
        parent.keys[i - 1] = sibling.keys.pop()
        if not child.leaf:
            child.children.insert(0, sibling.children.pop())
        self.stats["borrows"] += 1

    def _borrow_from_next(self, parent, i):
        """Rotate a key from the right sibling into children[i]."""
        child, sibling = parent.children[i], parent.children[i + 1]
        child.keys.append(parent.keys[i])
        parent.keys[i] = sibling.keys.pop(0)
        if not child.leaf:
            child.children.append(sibling.children.pop(0))
        self.stats["borrows"] += 1

    # ------------------------------------------------------------------ #
    # Iteration & misc                                                   #
    # ------------------------------------------------------------------ #

    def __iter__(self):
        """Yield all keys in ascending order."""
        yield from self._iter(self._root)

    def _iter(self, node):
        if node.leaf:
            yield from node.keys
            return
        for key, child in zip(node.keys, node.children):
            yield from self._iter(child)
            yield key
        yield from self._iter(node.children[-1])

    def __len__(self):
        return sum(len(n.keys) for n in self._nodes())

    def __contains__(self, key):
        return self.search(key)

    def height(self):
        """Number of levels (a lone root leaf has height 1)."""
        h, node = 1, self._root
        while not node.leaf:
            h += 1
            node = node.children[0]
        return h

    def _nodes(self):
        stack = [self._root]
        while stack:
            node = stack.pop()
            yield node
            if not node.leaf:
                stack.extend(node.children)

    # ------------------------------------------------------------------ #
    # Invariant checking (used heavily by the tests)                     #
    # ------------------------------------------------------------------ #

    def check_invariants(self):
        """Raise AssertionError if any structural invariant is violated.

        Checks: key bounds (<= 3 everywhere, >= 1 except the root),
        internal fan-out (children == keys + 1), and that every leaf sits
        at the same depth. Returns that common leaf depth.
        """
        depths = set()

        def walk(node, depth, is_root):
            assert len(node.keys) <= MAX_KEYS, "node exceeds 3 keys"
            if is_root:
                assert node.leaf or len(node.keys) >= 1, "empty internal root"
            else:
                assert len(node.keys) >= MIN_KEYS, "underflowing non-root node"
            if not node.leaf:
                assert len(node.children) == len(node.keys) + 1, \
                    "internal node must have keys + 1 children"
                for child in node.children:
                    walk(child, depth + 1, False)
            else:
                depths.add(depth)

        walk(self._root, 0, True)
        assert len(depths) == 1, "leaves are not all at the same depth"
        return depths.pop()

