import bisect, random
from btree import BTree

for seed in range(300):
    rng = random.Random(seed)
    tree, ref = BTree(), []
    for op in range(2000):
        k = rng.randrange(100)
        r = rng.random()
        if r < 0.5:
            tree.insert(k)
            if k not in ref: bisect.insort(ref, k)
        else:
            tree.delete(k)
            i = bisect.bisect_left(ref, k)
            if i < len(ref) and ref[i] == k: ref.pop(i)
        if op % 100 == 0:
            assert list(tree) == ref and not tree.check_invariants() != tree.check_invariants()
print("extended fuzz OK")
